@namespace sv_bb1ab9d83d254201926c6a2d4d92b553.Components.Pages.Chat

<div class="message-panel">
    @if (Channel is not null)
    {
        <div class="message-panel-header">
            <h4># @Channel.Name</h4>
            <p class="channel-desc-header">@Channel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @foreach (var msg in Messages)
            {
                <MessageBubble Message="msg"
                               ThreadReplyCount="GetThreadReplyCount(msg.Id)"
                               OnOpenThread="OnOpenThread"
                               OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonText="Send"
                      OnSend="OnSendMessage" />
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Services.Channel? Channel { get; set; }
    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadOlderMessages { get; set; }
    [Parameter] public EventCallback<Services.Message> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private int GetThreadReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers loading older messages
        await OnLoadOlderMessages.InvokeAsync();
    }
}

